package com.chattabhotkeys;

import com.chattabhotkeys.ChatTabs.ChatMode;
import com.chattabhotkeys.ChatTabs.ChatTab;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import java.util.EnumSet;
import java.util.Set;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;

@ConfigGroup(ChatTabHotkeysConfig.GROUP)
public interface ChatTabHotkeysConfig extends Config
{
	String GROUP = "chattabhotkeys";

	@ConfigSection(
		name = "Tab hotkeys & close",
		description = "One hotkey per chat tab, plus closing the chat. Defaults are Ctrl+1–7; press a tab's hotkey "
			+ "again to close the chat. Bind function keys or modifier combos so binds don't fire while typing.",
		position = 0
	)
	String tabsSection = "tabsSection";

	@ConfigSection(
		name = "Clear history",
		description = "Clear a chat tab's history like the right-click 'Clear history' entry. 'Clear current tab' "
			+ "clears whichever tab is shown; the per-tab binds clear that tab without switching to it. All no-op "
			+ "on the Game and All tabs.",
		position = 1
	)
	String clearSection = "clearSection";

	@ConfigSection(
		name = "Chat input mode",
		description = "Set which channel your typed messages go to, like the right-click 'Set chat mode' on the All tab. "
			+ "Group only works while you are in a group ironman group.",
		position = 2
	)
	String modeSection = "modeSection";

	// ------------------------------------------------------------------
	// Tab hotkeys — game order: All, Game, Public, Private, Channel, Clan, Trade.
	// Default to Ctrl+1..7 (typing-safe: Ctrl combos never leak into chat).
	// ------------------------------------------------------------------
	@ConfigItem(keyName = "tabAll", name = "All", description = "Show the All tab.", position = 0, section = tabsSection)
	default Keybind tabAll()
	{
		return new Keybind(KeyEvent.VK_1, InputEvent.CTRL_DOWN_MASK);
	}

	@ConfigItem(keyName = "tabGame", name = "Game", description = "Show the Game tab.", position = 1, section = tabsSection)
	default Keybind tabGame()
	{
		return new Keybind(KeyEvent.VK_2, InputEvent.CTRL_DOWN_MASK);
	}

	@ConfigItem(keyName = "tabPublic", name = "Public", description = "Show the Public tab.", position = 2, section = tabsSection)
	default Keybind tabPublic()
	{
		return new Keybind(KeyEvent.VK_3, InputEvent.CTRL_DOWN_MASK);
	}

	@ConfigItem(keyName = "tabPrivate", name = "Private", description = "Show the Private tab.", position = 3, section = tabsSection)
	default Keybind tabPrivate()
	{
		return new Keybind(KeyEvent.VK_4, InputEvent.CTRL_DOWN_MASK);
	}

	@ConfigItem(keyName = "tabChannel", name = "Channel", description = "Show the Channel tab.", position = 4, section = tabsSection)
	default Keybind tabChannel()
	{
		return new Keybind(KeyEvent.VK_5, InputEvent.CTRL_DOWN_MASK);
	}

	@ConfigItem(keyName = "tabClan", name = "Clan", description = "Show the Clan tab.", position = 5, section = tabsSection)
	default Keybind tabClan()
	{
		return new Keybind(KeyEvent.VK_6, InputEvent.CTRL_DOWN_MASK);
	}

	@ConfigItem(keyName = "tabTrade", name = "Trade", description = "Show the Trade tab.", position = 6, section = tabsSection)
	default Keybind tabTrade()
	{
		return new Keybind(KeyEvent.VK_7, InputEvent.CTRL_DOWN_MASK);
	}

	// ------------------------------------------------------------------
	// Close chat + clear history
	// ------------------------------------------------------------------
	@ConfigItem(
		keyName = "closeOnRepeat",
		name = "Close on repeat",
		description = "Pressing the same tab's hotkey again closes the chat. "
			+ "When off, pressing again just re-shows the tab. "
			+ "Closing only works in resizable mode (no-op in fixed mode).",
		position = 7,
		section = tabsSection
	)
	default boolean closeOnRepeat()
	{
		return true;
	}

	@ConfigItem(
		keyName = "closeChat",
		name = "Close chat",
		description = "Toggle the chat closed/open. Closed re-opens to the last tab. "
			+ "Only works in resizable mode (no-op in fixed mode).",
		position = 8,
		section = tabsSection
	)
	default Keybind closeChat()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "cycleTab",
		name = "Cycle tab",
		description = "Step to the next tab in the list below. Wraps around; opens the chat if it is closed.",
		position = 9,
		section = tabsSection
	)
	default Keybind cycleTab()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "cycleTabs",
		name = "Tabs to cycle",
		description = "The tabs the Cycle tab key steps through, in game order. Deselect to leave a tab out; "
			+ "an empty list disables the cycle.",
		position = 10,
		section = tabsSection
	)
	default Set<ChatTab> cycleTabs()
	{
		return EnumSet.allOf(ChatTab.class);
	}

	// ------------------------------------------------------------------
	// Clear history — the current tab, plus one bind per clearable tab
	// (Public, Private, Channel, Clan, Trade). Game/All can't be cleared.
	// ------------------------------------------------------------------
	@ConfigItem(
		keyName = "clearHistory",
		name = "Clear current tab",
		description = "Clear the currently-shown tab's history (no-op on the Game and All tabs).",
		position = 0,
		section = clearSection
	)
	default Keybind clearHistory()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "clearPublic",
		name = "Clear: Public",
		description = "Clear the Public tab's history without switching to it.",
		position = 1,
		section = clearSection
	)
	default Keybind clearPublic()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "clearPrivate",
		name = "Clear: Private",
		description = "Clear the Private tab's history without switching to it.",
		position = 2,
		section = clearSection
	)
	default Keybind clearPrivate()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "clearChannel",
		name = "Clear: Channel",
		description = "Clear the Channel (friends chat) tab's history without switching to it.",
		position = 3,
		section = clearSection
	)
	default Keybind clearChannel()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "clearClan",
		name = "Clear: Clan",
		description = "Clear the Clan tab's history without switching to it.",
		position = 4,
		section = clearSection
	)
	default Keybind clearClan()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "clearTrade",
		name = "Clear: Trade",
		description = "Clear the Trade tab's history without switching to it.",
		position = 5,
		section = clearSection
	)
	default Keybind clearTrade()
	{
		return Keybind.NOT_SET;
	}

	// ------------------------------------------------------------------
	// Chat input mode — which channel typed messages go to.
	// ------------------------------------------------------------------
	@ConfigItem(
		keyName = "setModePublic",
		name = "Set mode: Public",
		description = "Type into Public chat.",
		position = 0,
		section = modeSection
	)
	default Keybind setModePublic()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "setModeChannel",
		name = "Set mode: Channel",
		description = "Type into your friends chat channel.",
		position = 1,
		section = modeSection
	)
	default Keybind setModeChannel()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "setModeClan",
		name = "Set mode: Clan",
		description = "Type into your clan chat.",
		position = 2,
		section = modeSection
	)
	default Keybind setModeClan()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "setModeGuest",
		name = "Set mode: Guest clan",
		description = "Type into a guest clan chat.",
		position = 3,
		section = modeSection
	)
	default Keybind setModeGuest()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "setModeGroup",
		name = "Set mode: Group",
		description = "Type into group ironman chat. Only works while in a group.",
		position = 4,
		section = modeSection
	)
	default Keybind setModeGroup()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "cycleMode",
		name = "Cycle mode",
		description = "Step to the next mode in the list below. Wraps around.",
		position = 5,
		section = modeSection
	)
	default Keybind cycleMode()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "cycleModes",
		name = "Modes to cycle",
		description = "The chat input modes the Cycle mode key steps through, in game order. An empty list "
			+ "disables the cycle. Group is left out by default: the game resets it to your current mode "
			+ "when you are not in a group ironman group.",
		position = 6,
		section = modeSection
	)
	default Set<ChatMode> cycleModes()
	{
		return EnumSet.of(ChatMode.PUBLIC, ChatMode.CHANNEL, ChatMode.CLAN, ChatMode.GUEST);
	}
}

package com.chattabhotkeys;

import com.chattabhotkeys.ChatTabs.ChatMode;
import com.chattabhotkeys.ChatTabs.ChatTab;
import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.function.Supplier;
import javax.inject.Inject;
import net.runelite.api.ChatLineBuffer;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MessageNode;
import net.runelite.api.ScriptID;
import net.runelite.api.events.VarClientIntChanged;
import net.runelite.api.gameval.VarClientID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.Keybind;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.HotkeyListener;

@PluginDescriptor(
	name = "Chat Tab Hotkeys",
	description = "Configurable hotkeys to switch, cycle, and close chat tabs, clear history, and set chat mode",
	tags = {"chat", "chatbox", "tab", "hotkey", "keybind", "shortcut", "switch", "cycle", "clear", "mode", "channel"}
)
public class ChatTabHotkeysPlugin extends Plugin
{
	/** Value {@code VarClientID.CHAT_VIEW} holds when the chat is collapsed (resizable mode). */
	private static final int CHAT_VIEW_CLOSED = 1337;

	/**
	 * Chat-UI redraw procs run after writing CHAT_VIEW, to repaint what {@code setVarcIntValue} alone
	 * doesn't (the game only reacts to the varc when its own scripts run). All are benign, packet-free
	 * redraws with no {@code ScriptID} constant, called by literal id; none switches an interface or
	 * replays a widget listener.
	 */
	private static final int REDRAW_CHAT_BUTTONS = 178;          // [proc,redraw_chat_buttons]: tab-button highlight
	private static final int TOPLEVEL_CHATBOX_BACKGROUND = 923;  // [proc,toplevel_chatbox_background]: shows/hides the resizable chat frame
	private static final int CHAT_ALERT_SET = 183;              // [proc,chat_alert_set](tab,state): clears a tab's unread/flash (client varcs 44-48/438 only)

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private KeyManager keyManager;

	@Inject
	private ChatTabHotkeysConfig config;

	private final List<HotkeyListener> hotkeys = new ArrayList<>();

	/** Which tab to re-open to when the close hotkey expands a collapsed chat. */
	private ChatTab lastTab = ChatTab.ALL;

	/**
	 * The mode the mode-cycle last tried to set. Used only to step past Group: Group (GIM) reverts the
	 * mode var to the previous mode when the player isn't in a group, so without this the cycle would
	 * read the reverted var and retry Group forever. When the last step was Group and the var still
	 * holds {@link #groupRevertValue}, the cycle resumes from Group's slot and steps past it.
	 */
	private ChatMode lastCycledMode = null;

	/**
	 * The mode value the var held right before the cycle last wrote Group — i.e. the value Group reverts
	 * to when the player isn't in a group. If the var later shows a <em>different</em> value the player
	 * changed the mode themselves (e.g. the right-click "Set chat mode"), so the cycle drops the Group
	 * step-past and resyncs to the var. {@code -1} when the last step wasn't Group.
	 */
	private int groupRevertValue = -1;

	@Override
	protected void startUp()
	{
		register(config::tabAll, () -> onTabHotkey(ChatTab.ALL));
		register(config::tabGame, () -> onTabHotkey(ChatTab.GAME));
		register(config::tabPublic, () -> onTabHotkey(ChatTab.PUBLIC));
		register(config::tabPrivate, () -> onTabHotkey(ChatTab.PRIVATE));
		register(config::tabChannel, () -> onTabHotkey(ChatTab.CHANNEL));
		register(config::tabClan, () -> onTabHotkey(ChatTab.CLAN));
		register(config::tabTrade, () -> onTabHotkey(ChatTab.TRADE));

		register(config::cycleTab, this::onCycleTabHotkey);

		register(config::closeChat, this::onCloseHotkey);
		register(config::clearHistory, this::onClearHistoryHotkey);
		register(config::clearPublic, () -> clearTab(ChatTab.PUBLIC));
		register(config::clearPrivate, () -> clearTab(ChatTab.PRIVATE));
		register(config::clearChannel, () -> clearTab(ChatTab.CHANNEL));
		register(config::clearClan, () -> clearTab(ChatTab.CLAN));
		register(config::clearTrade, () -> clearTab(ChatTab.TRADE));

		register(config::setModePublic, () -> applyChatMode(ChatMode.PUBLIC));
		register(config::setModeChannel, () -> applyChatMode(ChatMode.CHANNEL));
		register(config::setModeClan, () -> applyChatMode(ChatMode.CLAN));
		register(config::setModeGuest, () -> applyChatMode(ChatMode.GUEST));
		register(config::setModeGroup, () -> applyChatMode(ChatMode.GROUP));
		register(config::cycleMode, this::onCycleModeHotkey);
	}

	@Override
	protected void shutDown()
	{
		for (HotkeyListener listener : hotkeys)
		{
			keyManager.unregisterKeyListener(listener);
		}
		hotkeys.clear();
	}

	@Provides
	ChatTabHotkeysConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ChatTabHotkeysConfig.class);
	}

	/**
	 * Tracks the last-shown tab from the game var, so mouse-driven tab switches keep
	 * {@link #lastTab} correct for the close→reopen path. When the chat collapses,
	 * CHAT_VIEW no longer maps to a tab, so we keep the previous value.
	 */
	@Subscribe
	public void onVarClientIntChanged(VarClientIntChanged event)
	{
		if (event.getIndex() == VarClientID.CHAT_VIEW)
		{
			rememberCurrentTab();
		}
	}

	/** Remembers the currently-shown tab (if any) for the close -> reopen path. */
	private void rememberCurrentTab()
	{
		ChatTab tab = currentTab();
		if (tab != null)
		{
			lastTab = tab;
		}
	}

	// ----------------------------------------------------------------------
	// Actions (client thread)
	// ----------------------------------------------------------------------

	private void onTabHotkey(ChatTab target)
	{
		if (!isChatClosed() && currentTab() == target)
		{
			// Target already shown. A repeat collapses the chat when closeOnRepeat is on (resizable
			// only; fixed mode can't collapse). Otherwise it's a visual no-op.
			if (config.closeOnRepeat() && client.isResized())
			{
				lastTab = target;
				collapseChat();
			}
			return;
		}

		switchTab(target);
		rememberCurrentTab();
	}

	/**
	 * Steps to the next selected chat tab (game order, wrapping). Reads the shown tab from the game var so
	 * mouse clicks stay in sync; when the chat is collapsed it resumes from {@link #lastTab}. If the shown
	 * tab isn't in the selection it starts at the first selected tab. No-ops when the selection is empty.
	 */
	private void onCycleTabHotkey()
	{
		List<ChatTab> tabs = cyclableTabs();
		if (tabs.isEmpty())
		{
			return;
		}

		ChatTab current = isChatClosed() ? lastTab : currentTab();
		int idx = current == null ? -1 : tabs.indexOf(current);
		ChatTab next = tabs.get((idx + 1) % tabs.size());
		switchTab(next);
		rememberCurrentTab();
	}

	private void onCloseHotkey()
	{
		if (isChatClosed())
		{
			switchTab(lastTab);
		}
		else if (client.isResized())
		{
			rememberCurrentTab();
			collapseChat();
		}
		// Fixed mode: chat can't collapse, so this is a no-op.
	}

	/** Clears the currently-shown tab (the original "Clear history" bind, now "Clear current tab"). */
	private void onClearHistoryHotkey()
	{
		clearTab(currentTab());
	}

	/**
	 * Clears {@code tab}'s history — used by both the current-tab bind and the per-tab clear binds.
	 * No-ops when {@code tab} is null (chat collapsed, no current tab) or the tab can't be cleared
	 * (Game/All). Per-tab callers always pass a non-null clearable constant, so this clears regardless
	 * of which tab is shown or whether the chat is collapsed.
	 */
	private void clearTab(ChatTab tab)
	{
		if (tab == null || !tab.supportsClear)
		{
			return;
		}

		// Native clear, ported from RuneLite's ChatHistoryPlugin: drop every message node
		// of the tab's chat types from the client's line buffers, then rebuild the chatbox.
		// Note: this doesn't fire the "Clear history" menu event, so if RuneLite's own Chat
		// History plugin is enabled with "retain chat history", a hotkey-cleared tab can
		// repopulate on relog/world-hop. Acceptable (see spec.md → Known limitations).
		boolean removed = false;
		for (ChatMessageType type : tab.messageTypes)
		{
			ChatLineBuffer buffer = client.getChatLineMap().get(type.getType());
			if (buffer == null)
			{
				continue;
			}

			for (MessageNode line : buffer.getLines().clone())
			{
				if (line != null)
				{
					buffer.removeMessageNode(line);
					removed = true;
				}
			}
		}

		if (removed)
		{
			client.runScript(ScriptID.SPLITPM_CHANGED);
		}
	}

	/**
	 * Sets which channel typed messages go to, the game's own way: write the mode var and rerun the
	 * chatbox-input build script so the input line redraws. Group (GIM) auto-resets to the current
	 * mode if the player isn't in a group. Only sets the target channel — never inserts message text.
	 */
	private void applyChatMode(ChatMode mode)
	{
		// Clear the cycle's Group-step tracker: a direct mode change (the Set-mode binds) resets where
		// the cycle resumes from. onCycleModeHotkey re-sets it right after calling this.
		lastCycledMode = null;
		groupRevertValue = -1;
		client.setVarcIntValue(VarClientID.CHATBOX_MODE, mode.value);
		client.runScript(ScriptID.CHAT_PROMPT_INIT);
	}

	/**
	 * Steps to the next selected chat input mode (game order, wrapping). Normally advances from the mode
	 * the game var reports, so manual (right-click) changes stay in sync. The exception is Group: it
	 * reverts the var when the player isn't in a GIM group, so if our last step set Group and the var
	 * still holds the value it reverted to, we advance from Group's slot — stepping past it instead of
	 * retrying it forever. If the player changed the mode themselves in between, the var shows a
	 * different value and we resync to it. If the resolved current mode isn't selected, it starts at the
	 * first selected mode. No-ops when the selection is empty.
	 */
	private void onCycleModeHotkey()
	{
		List<ChatMode> modes = cyclableModes();
		if (modes.isEmpty())
		{
			return;
		}

		int currentValue = client.getVarcIntValue(VarClientID.CHATBOX_MODE);
		// Step past Group only if our last step set Group and the var still holds the value Group
		// reverted to. A different value means the player changed the mode themselves since, so read it
		// straight from the var (keeps manual right-click changes in sync).
		boolean groupReverted = lastCycledMode == ChatMode.GROUP
			&& currentValue != ChatMode.GROUP.value
			&& currentValue == groupRevertValue;
		ChatMode current = groupReverted ? ChatMode.GROUP : ChatMode.byValue(currentValue);

		int idx = current == null ? -1 : modes.indexOf(current);
		ChatMode next = modes.get((idx + 1) % modes.size());
		applyChatMode(next);
		lastCycledMode = next;
		if (next == ChatMode.GROUP)
		{
			groupRevertValue = currentValue;
		}
	}

	/** The selected tabs for the tab cycle, always in game order (All..Trade) regardless of pick order. */
	private List<ChatTab> cyclableTabs()
	{
		Set<ChatTab> selected = config.cycleTabs();
		List<ChatTab> tabs = new ArrayList<>();
		for (ChatTab tab : ChatTab.values())
		{
			if (selected.contains(tab))
			{
				tabs.add(tab);
			}
		}
		return tabs;
	}

	/** The selected input modes for the mode cycle, always in game order (Public..Group). */
	private List<ChatMode> cyclableModes()
	{
		Set<ChatMode> selected = config.cycleModes();
		List<ChatMode> modes = new ArrayList<>();
		for (ChatMode mode : ChatMode.values())
		{
			if (selected.contains(mode))
			{
				modes.add(mode);
			}
		}
		return modes;
	}

	// ----------------------------------------------------------------------
	// Tab switch / close: write the CHAT_VIEW varc + a benign redraw. No packet,
	// no interface-switch clientscript — the switch is the varc; the procs only repaint.
	// ----------------------------------------------------------------------

	/** Switches to / opens {@code tab} by writing CHAT_VIEW (the game's active-tab varc) + a rebuild. */
	private void switchTab(ChatTab tab)
	{
		client.setVarcIntValue(VarClientID.CHAT_VIEW, tab.tabIndex);
		// Clear the switched-to tab's unread/flash, exactly as the native switch does (must run
		// before REDRAW_CHAT_BUTTONS, which reads the alert varc to pick the flash graphic).
		client.runScript(CHAT_ALERT_SET, tab.tabIndex, 0);
		redrawChat();
	}

	/**
	 * Collapses the chat by setting CHAT_VIEW to the collapse sentinel and rebuilding. Only meaningful
	 * in resizable mode; the caller must ensure {@code client.isResized()} (fixed mode never collapses).
	 */
	private void collapseChat()
	{
		client.setVarcIntValue(VarClientID.CHAT_VIEW, CHAT_VIEW_CLOSED);
		redrawChat();
	}

	/**
	 * Repaints the chat UI to reflect the CHAT_VIEW varc just written: frame collapse/expand + background
	 * ({@link #TOPLEVEL_CHATBOX_BACKGROUND}), the tab-button highlight ({@link #REDRAW_CHAT_BUTTONS}), then
	 * a chatbox + split private-chat rebuild ({@code ScriptID.SPLITPM_CHANGED}). All three are packet-free
	 * client-side redraws.
	 *
	 * <p>SPLITPM_CHANGED runs both the chatbox rebuild ({@code ~rebuildchatbox}) — a superset of
	 * {@code BUILD_CHATBOX} — and the split private-message overlay rebuild ({@code ~rebuildpmbox}), which
	 * BUILD_CHATBOX alone never runs. Only the pmbox rebuild re-evaluates the overlay's hide/show guard
	 * (split-chat enabled AND (CHAT_VIEW != {@value #CHAT_VIEW_CLOSED} OR the "hide private chat when the
	 * chatbox is hidden" setting is off)). Without it a collapse/reopen wrote CHAT_VIEW but left the split
	 * overlay stale until some later event (an incoming message, the redraw timer) happened to rebuild it —
	 * the delayed, inconsistent hide the native mouse toggle never has (it ends with the same pmbox
	 * rebuild). The proc self-gates on the split-chat vars, so it's a no-op when split chat is off.
	 */
	private void redrawChat()
	{
		client.runScript(TOPLEVEL_CHATBOX_BACKGROUND);
		client.runScript(REDRAW_CHAT_BUTTONS);
		client.runScript(ScriptID.SPLITPM_CHANGED);
	}

	private void register(Supplier<Keybind> keybind, Runnable action)
	{
		HotkeyListener listener = new HotkeyListener(keybind)
		{
			@Override
			public void hotkeyPressed()
			{
				clientThread.invoke(() ->
				{
					if (client.getGameState() == GameState.LOGGED_IN)
					{
						action.run();
					}
				});
			}
		};
		keyManager.registerKeyListener(listener);
		hotkeys.add(listener);
	}

	// ----------------------------------------------------------------------
	// State reads (from game vars, so mouse clicks stay in sync)
	// ----------------------------------------------------------------------

	private ChatTab currentTab()
	{
		return ChatTab.byTabIndex(client.getVarcIntValue(VarClientID.CHAT_VIEW));
	}

	private boolean isChatClosed()
	{
		// Collapsing only exists in resizable mode; in fixed mode the chat is never "closed".
		return client.isResized()
			&& client.getVarcIntValue(VarClientID.CHAT_VIEW) == CHAT_VIEW_CLOSED;
	}
}

package com.chattabhotkeys;

import java.util.Locale;
import net.runelite.api.ChatMessageType;

/**
 * Static data for the seven chat tabs.
 *
 * The {@link ChatTab#tabIndex} matches the value the game stores in {@code VarClientID.CHAT_VIEW}
 * while that tab is shown; it is the value written to switch to that tab. The per-tab
 * {@link ChatTab#messageTypes} are ported from RuneLite's own
 * {@code net.runelite.client.plugins.chathistory.ChatboxTab} and drive native clear-history.
 */
final class ChatTabs
{
	private ChatTabs()
	{
	}

	/**
	 * {@code supportsClear} marks the channel-type tabs whose history can be cleared; Game and All
	 * cannot (that action no-ops there).
	 */
	enum ChatTab
	{
		ALL(0, false),
		GAME(1, false),
		PUBLIC(2, true,
			ChatMessageType.PUBLICCHAT, ChatMessageType.AUTOTYPER,
			ChatMessageType.MODCHAT, ChatMessageType.MODAUTOTYPER),
		PRIVATE(3, true,
			ChatMessageType.PRIVATECHAT, ChatMessageType.PRIVATECHATOUT,
			ChatMessageType.MODPRIVATECHAT, ChatMessageType.LOGINLOGOUTNOTIFICATION),
		CHANNEL(4, true,
			ChatMessageType.FRIENDSCHATNOTIFICATION, ChatMessageType.FRIENDSCHAT,
			ChatMessageType.CHALREQ_FRIENDSCHAT),
		CLAN(5, true,
			ChatMessageType.CLAN_CHAT, ChatMessageType.CLAN_MESSAGE,
			ChatMessageType.CLAN_GUEST_CHAT, ChatMessageType.CLAN_GUEST_MESSAGE),
		TRADE(6, true,
			ChatMessageType.TRADE_SENT, ChatMessageType.TRADEREQ, ChatMessageType.TRADE,
			ChatMessageType.CHALREQ_TRADE, ChatMessageType.CLAN_GIM_CHAT, ChatMessageType.CLAN_GIM_MESSAGE);

		final int tabIndex;
		final boolean supportsClear;
		/** Empty for tabs without clear-history. */
		final ChatMessageType[] messageTypes;

		ChatTab(int tabIndex, boolean supportsClear, ChatMessageType... messageTypes)
		{
			this.tabIndex = tabIndex;
			this.supportsClear = supportsClear;
			this.messageTypes = messageTypes;
		}

		/** The tab whose {@link #tabIndex} equals {@code index}, or null if none (e.g. chat closed). */
		static ChatTab byTabIndex(int index)
		{
			for (ChatTab tab : values())
			{
				if (tab.tabIndex == index)
				{
					return tab;
				}
			}
			return null;
		}

		/** Title-cased label for the "Tabs to cycle" multi-select list (e.g. PUBLIC -> "Public"). */
		@Override
		public String toString()
		{
			String n = name();
			return n.charAt(0) + n.substring(1).toLowerCase(Locale.ROOT);
		}
	}

	/**
	 * Chat input channel, i.e. which channel typed messages go to (the game's right-click
	 * "Set chat mode" on the All tab). Set by writing {@code VarClientID.CHATBOX_MODE} to
	 * {@link #value} and rerunning the chatbox-input build script. Group (GIM) auto-resets
	 * to the current mode if the player is not in a group, so it is left out of the default
	 * "Modes to cycle" selection.
	 */
	enum ChatMode
	{
		PUBLIC(0, "Public"),
		CHANNEL(1, "Channel"),
		CLAN(2, "Clan"),
		GUEST(3, "Guest clan"),
		GROUP(4, "Group");

		final int value;
		private final String label;

		ChatMode(int value, String label)
		{
			this.value = value;
			this.label = label;
		}

		/** The mode whose {@link #value} equals {@code value}, or null if none. */
		static ChatMode byValue(int value)
		{
			for (ChatMode mode : values())
			{
				if (mode.value == value)
				{
					return mode;
				}
			}
			return null;
		}

		/** Label for the "Modes to cycle" multi-select list. */
		@Override
		public String toString()
		{
			return label;
		}
	}
}

